import{_ as o,o as i,c as l,a3 as a}from"./chunks/framework.BZCmpA0A.js";const h=JSON.parse('{"title":"Spec 29：Windows 單指令 QEMU 桌面啟動器","description":"","frontmatter":{},"headers":[],"relativePath":"SPEC-29-desktop-launcher.md","filePath":"SPEC-29-desktop-launcher.md","lastUpdated":1793516179000}'),c={name:"SPEC-29-desktop-launcher.md"};function r(d,e,s,n,t,u){return i(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="spec-29-windows-單指令-qemu-桌面啟動器" tabindex="-1">Spec 29：Windows 單指令 QEMU 桌面啟動器 <a class="header-anchor" href="#spec-29-windows-單指令-qemu-桌面啟動器" aria-label="Permalink to &quot;Spec 29：Windows 單指令 QEMU 桌面啟動器&quot;">​</a></h1><p>日期：2026-11-01</p><p>狀態：已實作；本地 PowerShell、啟停、viewer、lock 與磁碟保護驗收完成。</p><h2 id="目標" tabindex="-1">目標 <a class="header-anchor" href="#目標" aria-label="Permalink to &quot;目標&quot;">​</a></h2><ul><li>Windows/WSL1 使用者從 repo 根目錄執行一個 PowerShell 指令，即完成建置、背景 QEMU 啟動及原生 VNC viewer 開啟。</li><li>關閉 viewer 時，透過本次 QMP session 關閉本次 QEMU；若 QMP 無法關閉，僅在 Linux PID 與唯一 VM 名稱相符時停止該 QEMU。</li><li>保留 <code>make run</code> 的 UART 文字操作，以及 Linux/WSLg 的 <code>make run-gui</code> 和手動 <code>make run-gui-vnc</code>。</li><li>防止建置更新被執行中 QEMU 使用的磁碟映像；提供 <code>-Snapshot</code> 使用獨立暫存映像。</li></ul><h2 id="工作範圍" tabindex="-1">工作範圍 <a class="header-anchor" href="#工作範圍" aria-label="Permalink to &quot;工作範圍&quot;">​</a></h2><p>新增 <code>tools/run-desktop.ps1</code>，支援 Windows PowerShell 5.1 與 PowerShell 7。Viewer 可由 <code>-ViewerPath</code> 指定，或從 PATH、專案 <code>build/tigervnc</code> 及 TigerVNC/TightVNC 標準安裝目錄尋找。VNC 和 QMP 使用動態、loopback-only 連接埠；啟動器使用獨立 session 名稱、pidfile、log 目錄與排他 lock。建置和 QEMU 輸出記錄在 <code>build/desktop-&lt;session-id&gt;</code>。</p><p>Makefile 將 GUI block image 路徑、VM name、serial output 和 pidfile 變成可覆寫變數，由 launcher 傳入，不維護另一份 QEMU 參數清單。預設磁碟路徑維持既有 <code>build/wuwaos.img</code> 和 <code>build/wuwaos-swap.img</code>，客體寫入照常保存。<code>-Snapshot</code> 將兩個 image 複製到本次 session 目錄，建置更新及 QEMU 都使用副本；結束後刪除副本並保留記錄。</p><p>啟動前檢查 WSL 執行環境及 running distributions 的 QEMU command line，若有程序參照本 repo WUFS 映像即拒絕更新。排他 lock 防止兩個 launcher 同時使用 repo images。透過 QMP greeting、capabilities 和 <code>query-name</code> 確認端點屬於本次 instance；正常關閉使用 QMP <code>quit</code>。Fallback 由 Linux <code>/proc/&lt;pid&gt;/cmdline</code> 驗證 <code>-name</code> 後才送 SIGTERM，不使用全名程序終止。</p><p>不新增測試程式碼，不更動 WSL/Windows 安全設定、AGENTS.md 或既有未追蹤檔案。</p><h2 id="執行步驟" tabindex="-1">執行步驟 <a class="header-anchor" href="#執行步驟" aria-label="Permalink to &quot;執行步驟&quot;">​</a></h2><ol><li>解析 repo 相對路徑，檢查磁碟映像、viewer、wsl.exe、WSL toolchain、運行中 QEMU 及 launcher lock。</li><li>選擇未使用的 loopback VNC/QMP ports；必要時建立隔離磁碟副本。</li><li>前景等待 WSL <code>disk-image</code> 建置結束；此階段不啟動 VM。建置完成後才透過共用 QEMU recipe 的 <code>run-gui-vnc-session</code> 啟動背景 VM，將 serial 轉存至 session log，並接上本次 QMP、pidfile 及磁碟路徑。<code>StartupTimeoutSeconds</code> 只計算 QEMU/QMP ready，不包含建置時間。</li><li>以 QMP greeting、<code>qmp_capabilities</code> 和唯一 VM name 驗證啟動，再開啟 Windows viewer；限時檢查 viewer process 與 QEMU 的 VNC client/service。</li><li>監看 viewer 和 QEMU；任一結束時關閉另一側，等待程序停止及 ports 釋放，移除 snapshot 副本並釋放排他 launcher lock（空 lock 檔可保留）。</li><li>更新 README、開機主題、程式碼導覽和歷史索引，記錄實際驗收及未執行項目。</li></ol><h2 id="驗收條件" tabindex="-1">驗收條件 <a class="header-anchor" href="#驗收條件" aria-label="Permalink to &quot;驗收條件&quot;">​</a></h2><ul><li>PowerShell 5.1 和 PowerShell 7 能解析並執行 launcher。</li><li>Viewer 正常開啟，QMP <code>query-vnc</code> 可見 loopback client；關閉 viewer 後本次 QEMU 結束、VNC/QMP ports 釋放。</li><li>QEMU 意外結束時 viewer 關閉；invalid viewer、依賴缺少、啟動逾時或 port 衝突有清楚錯誤並清理本次建立程序。</li><li>已有 QEMU/launcher 時拒絕第二次啟動，不終止其他 VM；失敗及 Snapshot 驗收前後，原始磁碟 SHA-256 相同。</li><li>文件建置成功；不新增任何測試程式碼。</li></ul><h2 id="驗收紀錄" tabindex="-1">驗收紀錄 <a class="header-anchor" href="#驗收紀錄" aria-label="Permalink to &quot;驗收紀錄&quot;">​</a></h2><p>環境為 Windows PowerShell 5.1、PowerShell 7、WSL1 Ubuntu、QEMU 8.2.2 與 TigerVNC 1.16.2；沒有新增測試程式碼。</p><ul><li>Windows PowerShell 5.1 與 PowerShell 7 parser 均通過；<code>npm run docs:build</code> 通過（VitePress 對大 chunk 發出既有體積提示）。</li><li>以 <code>powershell.exe -NoProfile -File tools/run-desktop.ps1 -Snapshot -StartupTimeoutSeconds 60</code> 實際建置並啟動。serial log 確認 VirtIO GPU 1280×720 scanout、tablet ready 及 WUWAOS shell 開機完成；launcher 的 QMP <code>query-vnc</code> 顯示 loopback service <code>5991</code> 與 client <code>127.0.0.1</code>。TigerVNC stderr 記錄已連到 <code>127.0.0.1:5991</code> 並完成 RFB 3.8 協議協商。</li><li>對本次 TigerVNC PID 發出停止後，launcher 以 QMP 正常關閉本次 QEMU並回傳 exit code 0。之後 WSL 沒有本次 QEMU；VNC <code>5991</code> 與 QMP <code>44882</code> TCP ports 均無 listener，Snapshot images 已刪除，session logs 保留。</li><li>啟動前後原始 <code>build/wuwaos.img</code> SHA-256 均為 <code>6BA61B2E9E6C5AF4931DD39D338619BF66BF25C5639BB916ADC59B6B62FD4989</code>；原始 swap SHA-256 均為 <code>F6DDB73F54CF434916200D752A0596B14DA7D6534FE0F8CF454E6B1C02078355</code>。</li><li>QEMU/viewer 活動時第二次 launcher 在建置前被 OS file lock 拒絕。<code>-Snapshot -ViewerPath C:\\missing\\viewer.exe</code> 於 viewer preflight 回報明確錯誤，未建置或修改映像；原始 image hashes 維持相同。</li><li>使用者另回報已驗證桌面畫面；此紀錄不把該回報擴大為人工滑鼠操作或本輪新截圖證據。</li></ul><h2 id="限制與未驗證" tabindex="-1">限制與未驗證 <a class="header-anchor" href="#限制與未驗證" aria-label="Permalink to &quot;限制與未驗證&quot;">​</a></h2><ul><li>本輪未刻意造成 QMP readiness timeout、QEMU 自行崩潰或 VNC 連接埠競態；其 cleanup 路徑以唯一 name、pidfile 與 Linux cmdline ownership check 實作，未作故障注入驗收。</li><li>本輪未另外執行 QMP <code>screendump</code>；Spec 28 保留的 guest framebuffer 截圖描述桌面像素，這一輪驗證的是 Windows viewer 的實際 VNC client 連線與關閉生命週期。</li><li>Windows viewer 實體滑鼠操作及 UI 自動擷取仍沿用 Spec 28 的 <code>NOT_RUN</code> 限制；QMP client 證據不代表人工滑鼠操作驗收。</li></ul>',19)])])}const w=o(c,[["render",r]]);export{h as __pageData,w as default};
